import type { ClinicalCase } from "./clinical-types";

// Original case-based questions. Construction helper only assembles the typed
// records; every vignette, answer, and option explanation below is authored.
// Clinical checks: AAOS OrthoInfo open fractures, compartment syndrome,
// nonunions and sprains; NIAMS arthritis/fibromyalgia/osteoporosis guidance.
// https://orthoinfo.aaos.org/en/diseases--conditions/compartment-syndrome/
// https://orthoinfo.aaos.org/en/diseases--conditions/open-fractures/
// https://www.niams.nih.gov/health-topics/fibromyalgia
export const mskCases: Record<string, ClinicalCase> = {};
function add(id:string,stem:string,answer:string,why:string,d:[string,string][],harderStem?:string){
  mskCases[id]={stem,answer,why,foils:d.map(([text,why])=>({text,why})),...(harderStem?{harderStem}:{})};
}

add("PATH_MSK_stages","Three weeks after a stable tibial fracture, follow-up evaluation identifies a fibrocartilaginous callus bridging the injury. Which healing stage is occurring?","Reparative stage","Fibrocartilaginous callus and subsequent woven bone bridge the fracture during repair.",[["Initial hematoma formation","The initial clot forms immediately after injury, before bridging callus."],["Early inflammatory stage","Early inflammation recruits repair cells before a substantial callus forms."],["Late remodeling stage","Remodeling reshapes established bone rather than creating the initial soft bridge."]],"A healing tibia has bridging fibrocartilage but has not regained its original architecture. Which stage accounts for this finding?");
add("PATH_MSK_stages__risk","A patient asks why swelling and a clot developed immediately after a femoral fracture. Which injury directly initiated the local healing response?","Disruption of bone and nearby blood vessels","Fracture tears vessels and releases blood, creating the hematoma that initiates local repair.",[["Breakdown of cartilage lining the nearby joint","Cartilage degeneration does not create the blood clot at a newly fractured shaft."],["Stretching of an adjacent ligament","A ligament injury can cause swelling, but the fracture hematoma begins with disruption of vessels at the broken bone."],["Resorption of an established bony callus","Callus resorption occurs later, after the initial injury response."]]);
add("PATH_MSK_stages__mechanism","A fracture initially developed a hematoma and now has a bridging callus. What should occur as successful healing continues?","The callus is replaced and reshaped into stronger organized bone","Callus provides an initial bridge; remodeling then improves bone organization and load-bearing structure.",[["The soft callus remains the final load-bearing structure","The early bridge must mineralize and remodel to restore greater strength."],["A new hematoma replaces the bridging callus","Hematoma formation is an initial response rather than the normal next step after callus formation."],["Fibrous tissue remains between mobile fracture ends","Persistent motion and a fibrous gap suggest impaired union rather than successful remodeling."]]);
add("PATH_MSK_stages__signs","At a routine fracture follow-up, the nurse compares current findings with the first week after injury. Which change best supports uncomplicated healing?","Pain and swelling decrease while supported limb function improves","Improving symptoms and function accompany increasing stability during ordinary healing.",[["New purulent drainage appears","Purulent drainage suggests infection, not expected healing."],["A previously aligned limb becomes more deformed","Increasing deformity raises concern for lost alignment."],["Pain abruptly intensifies with new numbness","New severe pain and numbness require urgent neurovascular assessment."]]);
add("PATH_MSK_stages__complications","A smoker with peripheral arterial disease has little callus several months after a tibial fracture. Which factor most directly threatens bone union?","Insufficient blood supply at the fracture site","Repair tissue requires oxygen and nutrients delivered through adequate local circulation.",[["Capillary ingrowth supplying the developing callus","Revascularization delivers the substrates needed for union."],["Osteoblast deposition of matrix between stable fragments","New matrix formation supports rather than threatens union."],["Progressive replacement of woven bone with organized bone","This is normal remodeling, not the perfusion deficit suggested by peripheral arterial disease."]]);
add("PATH_MSK_stages__tests","A patient recovering from a forearm fracture asks how the team will determine whether the fragments are joining. Which follow-up is most useful?","Serial radiographs combined with examination of stability and function","Interval images demonstrate bridging bone, while examination assesses functional progress.",[["A bone-density scan of the lumbar spine","DXA assesses generalized density, not whether this forearm fracture is bridging."],["A serum calcium measurement at one follow-up visit","Circulating calcium does not demonstrate local mechanical or radiographic union."],["An assessment of pain relief after an analgesic dose","Reduced pain after medication cannot establish structural healing."]]);
add("PATH_MSK_stages__management","A patient with a newly reduced fracture wants to improve healing. Which plan should the nurse reinforce?","Maintain prescribed stabilization and adequate energy, protein, and nutrient intake","Stable alignment and sufficient nutrition support the repair process.",[["Begin full weight bearing when resting pain first subsides","Pain can improve before the fracture is strong enough for unrestricted loading."],["Use a removable support according to comfort rather than the prescribed schedule","Protection should follow the stabilization plan rather than symptoms alone."],["Increase supplements while postponing review of a loose cast","Nutrition cannot compensate for inadequate fracture stability."]]);

add("PATH_MSK_osteoblast","A bone specimen shows cells depositing unmineralized organic matrix along a healing fracture. Which cells perform this function?","Osteoblasts","Osteoblasts synthesize osteoid, the organic matrix that subsequently mineralizes.",[["Osteoclasts","Osteoclasts resorb existing bone rather than depositing osteoid."],["Chondrocytes","Chondrocytes produce cartilage matrix rather than osteoid."],["Fibroblasts","Fibroblasts form fibrous connective tissue rather than the specialized osteoid produced by osteoblasts."]]);
add("PATH_MSK_osteoblast__risk","A patient recovering from prolonged undernutrition has impaired bone formation. Which relationship must be restored for balanced bone remodeling?","Coordinated osteoblast formation and osteoclast resorption","Bone strength depends on a regulated balance between formation and resorption.",[["Bone formation continuing without coordinated removal of old bone","Normal remodeling requires regulated formation and resorption."],["Bone resorption exceeding the amount of newly formed matrix","Net resorption reduces skeletal mass rather than restoring balanced remodeling."],["Cartilage production replacing osteoid formation","Cartilage is not a substitute for the osteoblast-derived matrix required for mature bone."]]);
add("PATH_MSK_osteoblast__mechanism","During fracture repair, a patient asks how the replacement bone is built. Which explanation correctly describes osteoblast activity?","They produce osteoid that can later become mineralized","Osteoblasts build the organic scaffold on which bone mineral is deposited.",[["They dissolve mineralized bone within a resorption compartment","Osteoclasts perform bone resorption."],["They maintain cartilage at articular surfaces","Chondrocytes maintain cartilage; osteoblasts form bone matrix."],["They maintain mature bone from within lacunae","That describes the role and location of osteocytes rather than matrix-producing osteoblasts."]]);
add("PATH_MSK_osteoblast__signs","A patient gradually regains bone strength after a fracture while new matrix appears on imaging. Which process best explains this recovery?","New bone formation integrated with remodeling","Osteoblast activity contributes matrix needed for repair and skeletal adaptation.",[["Resorption continuing faster than matrix replacement","Net loss of bone does not explain increasing fracture strength."],["Fibrous tissue persisting between unstable fracture ends","A persistent fibrous gap suggests impaired union, not recovery of bony strength."],["Cartilage remaining without replacement by a bony bridge","Early cartilage must be replaced by bone for the described recovery."]]);
add("PATH_MSK_osteoblast__complications","An older adult's bone resorption has exceeded bone formation for years. Which consequence should the nurse anticipate?","Reduced bone strength and increased fragility fracture risk","A sustained remodeling imbalance removes more bone than is replaced.",[["Increased cortical thickness and higher bone mass","Sustained resorption exceeding formation reduces rather than increases mass."],["Excess unmineralized osteoid from a mineralization defect","That describes osteomalacia, not the stated net loss through remodeling imbalance."],["An isolated cartilage defect with preserved bone quantity","The imbalance affects bone mass, not just the joint surface."]]);
add("PATH_MSK_osteoblast__tests","A patient has several low-trauma fractures and concern for abnormal bone turnover. Which assessment best evaluates the resulting skeletal deficit?","Bone-density assessment with directed metabolic evaluation","Bone density and selected metabolic studies help characterize skeletal weakness and its causes.",[["A joint-fluid crystal analysis","Crystal analysis evaluates crystal arthritis rather than generalized skeletal fragility."],["A distal neurovascular examination of one limb","This evaluates local perfusion and nerve function rather than bone mass."],["A radiograph of a single painful joint without metabolic studies","A local film does not adequately characterize generalized low-trauma fractures and their metabolic cause."]]);
add("PATH_MSK_osteoblast__management","A patient with poor dietary intake has low bone mass and a treatable metabolic disorder. Which plan supports osteoblast-dependent repair?","Correct nutritional deficits and treat the disorder disrupting bone turnover","Adequate substrates and correction of the underlying disorder support balanced bone formation.",[["Use prolonged unloading as the principal method of building bone mass","Unnecessary unloading promotes bone loss and does not correct the nutritional or metabolic cause."],["Manage discomfort while deferring treatment of the metabolic disorder","Symptom control leaves the cause of impaired formation untreated."],["Begin unrestricted high-impact exercise before evaluating fragility fractures","Loading must be individualized to fracture risk and does not replace correction of the documented deficits."]]);

add("PATH_MSK_open","After a motorcycle crash, a patient's tibia is fractured and a nearby wound communicates with the fracture. How should this injury be classified?","Open fracture","Communication between the fracture and an external wound defines an open fracture.",[["Closed fracture","A closed fracture has no communication with an external wound."],["Simple ankle sprain","A sprain injures a ligament rather than breaking the tibia."],["Isolated subluxation","Subluxation describes partial loss of joint alignment, not an exposed fracture."]]);
add("PATH_MSK_open__risk","A patient has a high-energy lower-leg injury. Which finding specifically makes the broken bone vulnerable to direct external contamination?","A skin wound that communicates with the fracture","A communicating wound creates a route from the environment to deep tissues and bone.",[["Bruising over intact skin only","Bruising alone does not prove external communication."],["Mild swelling with an intact skin barrier","Swelling alone does not define an open injury."],["A prior healed scar remote from the injury","A remote healed scar is not an open pathway to this fracture."]]);
add("PATH_MSK_open__mechanism","An open forearm fracture occurred in a dirty outdoor setting. Why is infection prevention an immediate concern?","The wound permits organisms to enter exposed deep tissue and bone","Loss of the protective skin barrier permits direct microbial contamination.",[["An infected bloodstream has seeded an otherwise protected fracture","Hematogenous spread is possible in other settings, but this wound supplies a direct contamination route."],["Reduced bone density permits organisms to cross intact skin","Bone density does not explain entry through the documented open wound."],["The sterile fracture hematoma has produced the organisms","The clot is not the source of bacteria introduced by environmental contamination."]]);
add("PATH_MSK_open__signs","A patient with an open lower-leg fracture has increasing numbness in the foot and difficulty moving the toes. Which additional assessment has immediate priority?","Distal circulation, sensation, and motor function","New neurologic changes after trauma require prompt neurovascular assessment.",[["The extent of bruising around the knee","Bruising is relevant to injury documentation but does not assess the new distal sensory and motor changes."],["The usual pain score before the injury","Baseline pain does not determine whether the foot is currently neurovascularly compromised."],["The condition of the wound dressing","The dressing needs review, but it does not replace the urgent distal neurovascular examination."]]);
add("PATH_MSK_open__complications","Several weeks after an open tibial fracture, a patient develops persistent wound drainage, fever, and focal bone pain. Which complication is most concerning?","Osteomyelitis at the injured bone","A contaminated open injury can progress to deep bone infection.",[["Acute compartment syndrome","This requires urgent evaluation when suspected, but the weeks-long draining wound is most consistent with bone infection."],["Aseptic delayed union","Delayed healing can cause pain, but fever and persistent wound drainage point to infection."],["Post-traumatic joint stiffness","Stiffness does not explain a draining wound with fever and focal bone pain."]]);
add("PATH_MSK_open__tests","Before and after stabilizing an open forearm fracture, which assessment should be documented to detect injury-related compromise?","Distal pulses, capillary refill, sensation, and movement","Repeated neurovascular findings provide a baseline and detect changes associated with injury or stabilization.",[["Wound size, contamination, and dressing saturation","These document the open wound but do not establish distal nerve and vessel function."],["Pain score and analgesic response","Pain assessment is important but does not provide the necessary neurovascular baseline."],["Radiographic fracture position and alignment","Images assess the bone but cannot replace a documented distal neurovascular examination."]]);
add("PATH_MSK_open__management","A patient arrives with an open contaminated tibial fracture. Which care pathway best addresses the injury's immediate infection and stabilization needs?","Urgent fracture care with antibiotics, debridement planning, stabilization, and tetanus review","Open fractures require prompt coordinated treatment to reduce contamination and protect injured tissues.",[["Manage as a closed fracture with splinting and routine follow-up","A communicating contaminated wound adds urgent infection-prevention and surgical needs."],["Close the skin wound before evaluating deep contamination","Superficial closure does not remove contamination or address devitalized deep tissue."],["Use antibiotics and dressings while postponing stabilization and wound evaluation","Antibiotics do not replace fracture stabilization and assessment for debridement."]]);

add("PATH_MSK_compartment","Six hours after a tibial fracture, a patient reports severe pain despite analgesia. The leg is tense, and passive toe movement sharply increases pain. Which condition is most concerning?","Acute compartment syndrome","Disproportionate pain, tense tissues, and pain with passive stretch suggest pressure-related ischemia.",[["Acute arterial occlusion","Arterial occlusion is another ischemic emergency, but tense tissues and passive-stretch pain after fracture most strongly suggest compartment syndrome."],["Expected post-fracture swelling","Escalating disproportionate pain and pain with passive stretch exceed reassuring uncomplicated swelling."],["An isolated peripheral nerve contusion","Nerve contusion can cause altered sensation but does not best explain the tense compartment and severe stretch pain."]],"After lower-leg trauma, a patient's analgesic requirement rises and passive toe movement causes marked pain. Which complication requires immediate evaluation?");
add("PATH_MSK_compartment__risk","A nurse reassesses patients after orthopedic injury. Which patient has the clearest immediate risk for acute compartment syndrome?","A patient with a swollen tibial fracture inside a constrictive cast","Bleeding and edema within a fixed space can compromise tissue perfusion.",[["A patient with a reduced wrist fracture, soft compartments, and improving pain","The improving symptoms and soft tissues are less concerning than swelling within a constrictive cast."],["A patient with a mild ankle sprain and intact distal sensation","The limited injury has less specific risk than a swollen tibial fracture in a tight cast."],["A patient with a stable finger fracture in a loose splint","This small stable injury lacks the major swelling and external constriction of the highest-risk option."]]);
add("PATH_MSK_compartment__mechanism","A patient with a crush injury develops pressure-related ischemia in the calf. Which mechanism explains the threatened muscle and nerve function?","Rising pressure impairs small-vessel perfusion within nonexpanding fascia","High intracompartmental pressure reduces the gradient needed to perfuse local tissue.",[["A clot obstructs the main artery supplying the limb","Arterial occlusion is a different cause of ischemia; the case specifies pressure within a muscle compartment."],["A contused nerve sends abnormal signals despite adequate tissue perfusion","A nerve contusion does not account for pressure-related ischemia of both muscle and nerve."],["Fluid accumulates inside the joint capsule","An effusion is intra-articular, whereas compartment syndrome develops within a constrained muscle compartment."]]);
add("PATH_MSK_compartment__signs","A patient in a forearm cast says the pain is worsening and the fingers feel tingling. Which finding most strongly reinforces concern for acute compartment syndrome?","Marked pain when the fingers are passively extended","Passive stretch increases pain in ischemic muscles within the affected compartment.",[["Itching under the cast with stable sensation","Itching without worsening ischemic symptoms is less supportive of compartment syndrome."],["Bruising that fades as the pain decreases","Improving bruising and pain favor ordinary recovery."],["Mild dependent finger swelling that improves with repositioning","This is less concerning than marked stretch pain accompanying paresthesia."]]);
add("PATH_MSK_compartment__complications","Acute compartment syndrome in a patient's forearm remains untreated. Which outcome is the nurse most concerned about preventing?","Irreversible muscle and nerve injury with loss of limb function","Sustained ischemia can produce necrosis and permanent disability.",[["Joint stiffness from a period of immobilization","Stiffness can complicate recovery, but untreated ischemia threatens irreversible soft-tissue damage."],["Delayed union of the fracture","Bony healing is important, but the immediate untreated compartment threat is muscle and nerve necrosis."],["Transient dependent edema after the injury","Sustained pressure-related ischemia can produce permanent injury rather than uncomplicated temporary edema."]]);
add("PATH_MSK_compartment__tests","The findings after a leg injury are concerning but not fully diagnostic for acute compartment syndrome. Which assessment can directly support the urgent clinical evaluation?","Measurement of pressure within the involved compartment","Pressure measurement can support the diagnosis when the clinical situation is uncertain.",[["Radiographs to reassess fracture alignment","Images describe bone position but do not measure muscle-compartment pressure."],["Doppler evaluation of major arterial flow","Major arteries can remain patent despite impaired capillary perfusion in a compartment."],["Serum creatine kinase measurement","CK may reflect muscle injury but does not directly establish the compartment pressure."]]);
add("PATH_MSK_compartment__management","A casted patient develops severe increasing calf pain, tense swelling, and pain with passive stretch. Which response is most appropriate?","Obtain immediate emergency surgical evaluation and address external constriction","Suspected acute compartment syndrome requires urgent assessment for decompression.",[["Give additional prescribed analgesia and reassess after the next routine round","Analgesia must not delay emergency assessment of suspected compartment ischemia."],["Elevate the leg well above heart level and observe for improvement","Marked elevation can reduce the perfusion gradient and does not replace urgent decompression assessment."],["Obtain a repeat fracture radiograph before escalating the neurovascular concern","Bone imaging should not delay urgent evaluation of the pressure emergency."]]);

add("PATH_MSK_compartment2","After forearm trauma, a patient has severe pain with passive finger extension and new numbness. The radial pulse remains palpable. How should the nurse interpret the pulse?","It does not exclude acute compartment syndrome","Small-vessel perfusion can fail while a larger artery still transmits a palpable pulse.",[["It favors a localized nerve contusion rather than a pressure emergency","A pulse does not distinguish a nerve contusion from compartment-related microvascular ischemia."],["It suggests expected post-traumatic swelling that can be followed routinely","The accompanying stretch pain and numbness require urgent evaluation despite the pulse."],["It establishes adequate perfusion of the muscle compartment","Large-vessel pulsation does not establish adequate capillary tissue perfusion."]]);
add("PATH_MSK_compartment2__risk","A patient has a bleeding muscle injury in the calf. Distal pulses are normal, but swelling continues inside an intact fascial space. Why is the patient still at risk?","Microcirculation can be compressed before major arterial flow disappears","Compartment pressure can compromise capillary perfusion without immediately eliminating pulses.",[["A patent large artery maintains capillary flow despite the rising tissue pressure","Pressure can compress the microcirculation while the large artery remains patent."],["A closed injury drains blood through the fascial boundary","An intact constrained fascial space limits accommodation and can retain pressure."],["The swelling threatens the joint surface rather than the enclosed muscle","The described blood and edema are within the muscle compartment, where nerves and muscle are vulnerable."]]);
add("PATH_MSK_compartment2__mechanism","A patient with a tight forearm compartment still has a palpable radial pulse. How can the hand retain a pulse while its muscles become ischemic?","Larger arteries may remain patent while local capillary perfusion falls","Pulse transmission and adequate microvascular tissue flow are not equivalent.",[["The nerve contusion changes sensation without affecting muscle perfusion","A nerve injury alone does not explain the documented ischemia within a tight compartment."],["Venous congestion creates swelling but preserves capillary oxygen delivery","Venous outflow impairment can reduce the perfusion gradient and contribute to ischemia."],["Distal pulsation measures the oxygen delivered to individual muscle fibers","A palpable arterial pulse is not a direct measure of microvascular oxygen delivery."]]);
add("PATH_MSK_compartment2__signs","A nurse is following a patient with a new lower-leg fracture. Which change warrants urgent escalation even with a warm foot and palpable pulse?","Increasing pain with passive stretch accompanied by paresthesia","Worsening stretch pain and neurologic symptoms can precede late arterial findings.",[["Bruising that is fading with less pain","Improving bruising and discomfort are less suggestive of new ischemia."],["Improving toe movement after swelling decreases","Functional improvement does not support escalating pressure."],["Stable sensation and decreasing analgesic requirements","Stable or improving findings are less concerning than new paresthesia."]]);
add("PATH_MSK_compartment2__complications","A clinician proposes waiting for absent pulses before evaluating a patient with suspected compartment syndrome. Which consequence should the nurse identify?","Treatment may be delayed until substantial tissue ischemia has occurred","Pulselessness is often late; waiting for it can permit permanent damage.",[["The wait improves diagnostic specificity without changing tissue viability","Ischemic tissue injury may progress during the delay."],["Pain medicine protects the muscle while the arterial pulse is monitored","Analgesia does not restore compartment perfusion or prevent necrosis."],["The principal consequence is delayed recognition of a skin infection","The immediate concern is progressive pressure-related ischemia, not a skin infection."]]);
add("PATH_MSK_compartment2__tests","A patient with a crush injury has a palpable pedal pulse. Which monitoring plan is most appropriate for detecting evolving compartment syndrome?","Serial pain, passive-stretch, sensory, motor, and tissue-tension assessments","Repeated multidimensional examination detects changes that a pulse check alone can miss.",[["Monitor radiographic alignment at scheduled intervals","Bone alignment does not track evolving compartment perfusion."],["Trend distal pulses and foot temperature","These are useful elements, but preserved large-vessel findings can miss early muscle ischemia."],["Track resting pain scores after each analgesic dose","Pain scores without stretch, sensory, motor, and tension findings provide an incomplete assessment."]]);
add("PATH_MSK_compartment2__management","A patient with possible compartment syndrome asks to delay evaluation because the pulse is still present. What is the best response?","Explain the risk and arrange urgent evaluation despite the pulse","Preserved pulses must not delay treatment of a clinically suspected emergency.",[["Offer reassurance based on the palpable pulse and reassess at the next routine round","A preserved pulse cannot exclude the pressure emergency suggested by the other findings."],["Increase analgesia and wait to see whether tingling resolves","Symptom treatment must not delay urgent evaluation of suspected compartment syndrome."],["Arrange a fracture-alignment radiograph before notifying the urgent team","A bone image does not assess the threatened compartment perfusion and should not delay escalation."]]);

add("PATH_MSK_sprain","A soccer player sustains a blow to the lateral knee. Examination identifies a partial tear of the medial collateral ligament. What type of injury is this?","Sprain","A ligament injury is a sprain; a muscle or tendon injury is a strain.",[["Muscle strain","The injured structure is a ligament, not a muscle or tendon."],["Subluxation","No partial loss of joint alignment is described."],["Fracture","The described lesion is not a break in bone."]]);
add("PATH_MSK_sprain__risk","A runner rolls an ankle inward and stretches its lateral supporting ligaments beyond their normal range. Which mechanism most directly caused the sprain?","Excessive force across a ligament stabilizing the joint","Sprains result from overstretching or tearing joint-supporting ligaments.",[["Eccentric loading that tears calf muscle fibers","A muscle-fiber injury is a strain rather than the described ligament injury."],["A compressive load that breaks the distal fibula","A break in bone is a fracture, not the mechanism defining a sprain."],["Translation that completely separates the ankle joint surfaces","That describes dislocation rather than stretching the lateral supporting ligaments."]]);
add("PATH_MSK_sprain__mechanism","A patient says that a sprain and strain are interchangeable terms. Which explanation should the nurse give?","A sprain affects a ligament; a strain affects muscle or tendon","The terms identify different injured connective-tissue structures.",[["A sprain affects muscle fibers; a strain affects ligaments","These structures are reversed: sprains involve ligaments and strains involve muscle or tendon."],["A sprain affects bone; a strain affects joint cartilage","Neither definition corresponds to the structures named by these injuries."],["A sprain means complete tearing; a strain means partial tearing","The terms distinguish tissues, not simply the degree of injury."]]);
add("PATH_MSK_sprain__signs","After twisting an ankle, a patient develops localized swelling, bruising, tenderness, and painful weight bearing. Radiographs show no fracture. Which finding pattern is compatible with a sprain?","Painful swelling and reduced function around the injured ligament","A sprain commonly produces localized soft-tissue symptoms after joint stress.",[["A fixed deformity with complete loss of joint congruity","That finding indicates dislocation rather than an uncomplicated ligament sprain."],["A focal cortical break visible on the ankle radiograph","A cortical break indicates fracture; the case states that no fracture was seen."],["Loss of active plantar flexion with a palpable Achilles gap","That pattern suggests tendon rupture rather than the injured ankle-supporting ligament."]]);
add("PATH_MSK_sprain__complications","A patient repeatedly returns to sport before rehabilitating a severe ankle sprain and now reports that the ankle gives way. Which complication is most likely?","Chronic joint instability","Severe or incompletely rehabilitated ligament injury can leave inadequate joint support.",[["Fixed loss of joint contact from an unreduced dislocation","The described recurrent giving way after ligament injury is instability rather than a continuously dislocated joint."],["An unhealed fracture at the lateral malleolus","The history identifies a sprain, not a documented fracture failing to unite."],["Isolated skin bruising with restored mechanical support","Persistent giving way indicates a support problem beyond resolving bruising."]]);
add("PATH_MSK_sprain__tests","A patient has medial knee pain after a lateral blow. Which evaluation most directly helps determine whether a supporting ligament was injured?","Focused examination of ligament stability with imaging when indicated","The history and targeted stability examination localize ligament injury; selected imaging evaluates severity and other injuries.",[["A knee radiograph to determine bone mineral density","An acute radiograph may detect fracture but does not directly establish ligament stability or quantify density."],["A calf-vein ultrasound to evaluate thrombosis","Venous imaging addresses a different cause of leg symptoms rather than traumatic ligament integrity."],["An inflammatory-marker panel to grade the ligament tear","Inflammatory markers cannot substitute for targeted stability examination and indicated imaging."]]);
add("PATH_MSK_sprain__management","A patient is discharged after evaluation of an uncomplicated ankle sprain. Which plan best supports recovery?","Protect the injured ligament, manage swelling and pain, and follow graded rehabilitation","Early protection followed by appropriate rehabilitation supports recovery and stability.",[["Resume sport once swelling falls, before strength and stability are reassessed","Reduced swelling does not establish functional recovery for cutting or jumping."],["Continue rigid immobilization after symptoms improve without beginning rehabilitation","Unnecessary prolonged immobilization can impair strength and function."],["Use analgesia to continue the usual training load during recovery","Masking pain does not protect the injured ligament from reinjury."]]);

add("PATH_MSK_sublux","After a shoulder injury, imaging shows the humeral head partly displaced but still in contact with the glenoid. How is this alignment abnormality classified?","Subluxation","Subluxation is a partial displacement with some joint contact maintained.",[["Complete dislocation","Complete dislocation implies loss of normal joint contact."],["Comminuted fracture","Comminution describes multiple bone fragments."],["Muscle strain alone","A strain does not itself describe the demonstrated joint displacement."]]);
add("PATH_MSK_sublux__risk","A patient with recurrent patellar subluxation asks why the kneecap shifts partly out of place during activity. Which factor can contribute?","Insufficient stabilizing support from lax or injured surrounding tissues","Trauma or ligamentous laxity can allow partial joint displacement.",[["Loss of bone mineral as the principal cause of ligamentous laxity","Bone mineral loss can increase fracture risk but does not directly explain deficient soft-tissue restraint."],["Joint cartilage wear with the patella remaining centered","Cartilage degeneration does not describe the recurrent partial displacement."],["Restored capsular tension and balanced dynamic support","These support stable alignment rather than explain recurrent subluxation."]]);
add("PATH_MSK_sublux__mechanism","An image confirms a subluxated joint. Which description should the nurse use to explain the finding?","The articular surfaces have lost some, but not all, normal contact","Partial loss of congruity differentiates subluxation from complete dislocation.",[["The articular surfaces have completely separated","Complete loss of contact describes dislocation rather than subluxation."],["A break has developed through the adjacent bone cortex","A break in bone defines fracture rather than partial joint displacement."],["The supporting tendon has torn while joint alignment remains normal","An isolated tendon tear is a different structural finding from loss of some articular contact."]]);
add("PATH_MSK_sublux__signs","A patient reports a shoulder that briefly slips and then partly returns after reaching overhead. Which finding supports evaluation for recurrent subluxation?","Episodes of joint shifting with pain and limited movement","A sense of slipping with functional limitation is compatible with joint instability.",[["Pain confined to a tendon without a sensation of slipping","A tendon disorder may cause shoulder pain but is less supportive of recurrent partial displacement."],["Gradual stiffness and crepitus without episodes of shifting","That pattern is more consistent with degenerative change than recurrent subluxation."],["A fixed deformity with complete persistent loss of joint contact","That describes complete dislocation rather than brief partial shifting."]]);
add("PATH_MSK_sublux__complications","A patient repeatedly sustains shoulder subluxations. Which problem warrants monitoring because of recurrent instability?","Damage to surrounding tissues or adjacent nerves and vessels","Repeated partial displacement can injure stabilizers and nearby neurovascular structures.",[["Generalized bone loss as the direct result of each episode","The local mechanical injury primarily threatens supporting tissues and nearby neurovascular structures."],["A bony callus bridging a fractured humeral shaft","A fracture callus is not the defining complication of recurrent partial joint displacement."],["Inflammatory polyarthritis developing from mechanical instability","Recurrent traumatic instability does not itself establish a systemic inflammatory arthritis."]]);
add("PATH_MSK_sublux__tests","A patient has a painful partially displaced shoulder after a fall. Which assessment should accompany imaging of joint alignment?","Distal circulation, sensation, and motor function","An alignment injury can affect adjacent nerves and vessels, requiring neurovascular assessment.",[["Shoulder pain severity after analgesia","Symptoms matter, but pain relief does not establish distal nerve and vessel integrity."],["The degree of deformity visible at the shoulder","Local appearance does not replace a distal neurovascular examination."],["Active range of motion of the affected joint","Movement is relevant, but it does not fully assess perfusion and sensation distal to the injury."]]);
add("PATH_MSK_sublux__management","A patient has a symptomatic traumatic subluxation confirmed on examination. Which plan is most appropriate?","Qualified reduction when indicated, followed by stabilization and rehabilitation","Restoring congruity and rebuilding support address both the current displacement and future instability.",[["Treat pain and return to activity once the discomfort falls","Pain relief does not establish restored alignment or stability."],["Use strengthening exercises before assessing the traumatic displacement","The symptomatic displacement must first receive appropriate qualified assessment and management."],["Restore joint position without planning subsequent stabilization or rehabilitation","The plan must also address the support deficits that contribute to recurrence."]]);

add("PATH_MSK_rhabdo","A patient rescued after prolonged entrapment has painful swollen muscles, dark urine, and markedly elevated creatine kinase. Which condition best explains the findings?","Rhabdomyolysis","Extensive muscle injury releases intracellular contents, including myoglobin and creatine kinase.",[["Acute deep-vein thrombosis","DVT may cause a swollen painful limb but does not explain marked CK elevation after extensive muscle compression."],["An isolated tendon rupture","A focal tendon injury does not explain extensive myocyte injury with myoglobin-associated dark urine."],["Hematuria from a urinary stone","A stone may discolor urine but does not explain painful injured muscles and a markedly elevated CK."]],"After prolonged entrapment, a patient has diffuse muscle tenderness and dark urine with a large CK elevation. Which diagnosis is most likely?");
add("PATH_MSK_rhabdo__risk","After a seizure lasting many minutes, a patient develops diffuse muscle tenderness. Which recent event most increases concern for rhabdomyolysis?","Sustained intense muscle activity during the seizure","Prolonged muscle activity can injure myocytes and release their contents.",[["A short gentle walk completed without symptoms","This does not provide the sustained damaging muscle activity described in the seizure."],["An isolated ankle inversion causing ligament tenderness","A localized ligament injury is different from extensive myocyte stress."],["A healed muscle strain with restored strength","A remote recovered strain does not explain new muscle injury after a prolonged seizure."]]);
add("PATH_MSK_rhabdo__mechanism","A patient with a crush injury develops elevated creatine kinase and myoglobin in the urine. What directly caused these findings?","Damaged skeletal muscle cells released intracellular proteins","Myocyte disruption releases CK and myoglobin into the circulation.",[["A damaged glomerulus allowed intact red cells into urine","Hematuria may darken urine but does not release skeletal-muscle CK and myoglobin."],["Red-cell destruction released hemoglobin into the circulation","Hemolysis can cause pigmenturia but does not account for the CK rise from crushed skeletal muscle."],["Reduced filtration concentrated normal urinary pigments","Concentration does not produce circulating muscle proteins from injured myocytes."]]);
add("PATH_MSK_rhabdo__signs","An endurance athlete has muscle pain after an extreme workout. Which additional pattern raises concern for rhabdomyolysis rather than ordinary postexercise soreness?","Muscle swelling and weakness with dark urine","Systemic evidence of muscle breakdown warrants evaluation; the complete classic triad need not be present.",[["Mild muscle soreness that improves with rest and normal urine","This is more compatible with ordinary recovery than extensive muscle breakdown."],["Tenderness confined to an ankle ligament with preserved muscle strength","A focal ligament injury does not explain the muscle-breakdown symptom pattern."],["Flank colic with visible blood in urine but no muscle swelling","A urinary stone may cause urine discoloration without the muscle findings of rhabdomyolysis."]]);
add("PATH_MSK_rhabdo__complications","A patient with extensive rhabdomyolysis has falling urine output and a rising potassium level. Which complication pair is most concerning?","Acute kidney injury and dangerous cardiac dysrhythmias","Myoglobin can contribute to kidney injury, while released potassium threatens cardiac conduction.",[["Urinary stone obstruction with reflex muscle cramps","This does not explain systemic potassium release after extensive myocyte injury."],["Fluid overload with dilutional hypokalemia","The case specifies rising potassium; rhabdomyolysis releases intracellular potassium and can injure kidneys."],["Lower urinary inflammation with preserved filtration","Falling urine output and electrolyte disturbance raise concern for renal injury rather than isolated cystitis."]]);
add("PATH_MSK_rhabdo__tests","A patient is evaluated after prolonged muscle compression. Which laboratory result most directly supports substantial skeletal muscle breakdown?","A marked elevation in serum creatine kinase","CK is released from injured skeletal muscle and is a key laboratory marker of rhabdomyolysis.",[["A positive urine culture","Urine culture detects infection rather than quantifying muscle-cell injury."],["An elevated serum creatinine","Creatinine assesses kidney function; it does not directly measure the extent of muscle-cell disruption."],["A urine dipstick positive for blood without microscopy","A heme-positive dipstick can reflect red cells, hemoglobin, or myoglobin and is not specific by itself."]]);
add("PATH_MSK_rhabdo__management","A patient with rhabdomyolysis is becoming oliguric. Which plan best addresses the major immediate risks?","Provide prescribed IV fluids while monitoring urine output, renal function, and electrolytes","Volume management and close renal/electrolyte monitoring address potentially serious complications.",[["Manage the muscle discomfort and defer electrolyte studies until the next visit","Renal injury and potassium disturbances can become urgent before pain resolves."],["Use oral intake as tolerated without assessing the falling urine output","Oliguria requires a monitored individualized renal and volume assessment."],["Continue an unchanged high fluid rate despite new signs of overload","Fluids must be adjusted to urine output, renal function, and volume status."]]);

add("PATH_MSK_osteoporosis","A 72-year-old patient sustains a vertebral compression fracture after lifting a grocery bag. DXA shows low bone mineral density; calcium, phosphate, vitamin D, and alkaline phosphatase are normal, with no evidence of a mineralization disorder. Which condition best explains this fragility?","Osteoporosis","Low bone mass and impaired microarchitecture increase susceptibility to low-trauma fractures.",[["Osteomyelitis","Infection produces a different focal destructive pattern rather than the described generalized low-mass fragility."],["Osteoarthritis","Articular degeneration does not by itself explain a low-trauma vertebral compression fracture with low bone mass."],["Osteomalacia","Defective mineralization is a competing cause of skeletal weakness, but the case supplies a normal mineral evaluation and no evidence of impaired mineralization."]],"A minor lifting movement produces a vertebral fracture in an older adult with low DXA measurements and a normal mineral evaluation, with no evidence of a mineralization defect or focal destructive lesion. Which condition is most likely?");
add("PATH_MSK_osteoporosis__risk","A postmenopausal patient has used systemic glucocorticoids for several years. Which factor most increases concern for osteoporosis?","Prolonged systemic glucocorticoid exposure","Chronic glucocorticoid therapy can impair bone formation and increase fracture risk.",[["Regular prescribed weight-bearing exercise","Appropriate exercise generally supports bone health rather than carrying the established risk of prolonged systemic steroids."],["Adequate calcium and vitamin D intake","Adequate intake supports the skeleton but does not account for the medication-associated risk."],["A short course of topical glucocorticoid on a small skin area","This limited exposure is less concerning for systemic bone loss than years of systemic therapy."]]);
add("PATH_MSK_osteoporosis__mechanism","A patient asks how osteoporosis weakens bone even when routine serum calcium is normal. Which explanation is accurate?","The amount and internal architecture of bone deteriorate","Osteoporosis reduces structural bone strength; serum calcium can remain within its reference range.",[["Bone matrix is formed but fails to mineralize adequately","That defines osteomalacia rather than the loss of bone mass and microarchitecture in osteoporosis."],["Articular cartilage thins while bone mass remains unchanged","Cartilage degeneration describes osteoarthritis, not generalized skeletal fragility."],["Excess marrow inflammation destroys a focal infected bone segment","This is an infectious mechanism, not the usual mechanism of osteoporosis."]]);
add("PATH_MSK_osteoporosis__signs","An older adult has gradually lost height and developed thoracic rounding. Which associated finding would support vertebral osteoporotic fractures?","New focal back pain after minimal strain","Vertebral fragility fractures can produce pain, height loss, and kyphotic deformity.",[["Pain localized to the paraspinal muscles after a strenuous workout","A muscular overuse pattern is less supportive of a fragility fracture than new focal vertebral pain after minimal strain."],["Sciatic pain radiating along one leg","Radicular pain suggests nerve-root involvement rather than directly identifying vertebral fragility fractures."],["Generalized proximal weakness with diffuse bone tenderness","This raises a competing metabolic or muscular problem rather than the focal vertebral fracture pattern."]]);
add("PATH_MSK_osteoporosis__complications","A patient with severe osteoporosis falls from standing height and cannot bear weight. Which complication requires prompt evaluation?","Hip fragility fracture","Osteoporotic bone can fracture after a low-energy fall.",[["A transient soft-tissue contusion","A contusion is possible after a fall, but inability to bear weight with severe osteoporosis requires evaluation for fracture."],["A degenerative knee pain flare","A chronic joint flare does not adequately explain the abrupt post-fall loss of weight-bearing ability."],["An isolated hamstring strain","A strain may cause pain, but skeletal fragility makes a hip fracture the priority concern."]]);
add("PATH_MSK_osteoporosis__tests","A patient with risk factors for osteoporosis asks which test measures bone mineral density. Which study should the nurse describe?","Dual-energy X-ray absorptiometry","DXA is used to measure bone mineral density and contributes to fracture-risk assessment.",[["Serum calcium measurement","Serum calcium does not directly quantify bone mineral density."],["Plain radiographs of one painful joint","A local radiograph can show structural injury but is not the standard quantitative density study."],["A serum bone-turnover marker panel","Turnover markers may inform selected assessments but do not replace DXA measurement of bone density."]]);
add("PATH_MSK_osteoporosis__management","A patient with osteoporosis is planning home care. Which plan best reduces fracture risk?","Combine appropriate bone-directed care with exercise, fall prevention, and adequate nutrition","Bone health and prevention of falls both contribute to reducing fractures.",[["Avoid weight-bearing activity until bone density returns to normal","Unnecessary inactivity can worsen strength, balance, and bone loss."],["Use calcium supplements as the complete fracture-prevention plan","Nutrition is one component; fall prevention, appropriate exercise, and indicated bone-directed treatment also matter."],["Stop bone-directed therapy when pain is absent","Osteoporosis can be painless until fracture; symptoms alone do not determine treatment need."]]);

add("PATH_MSK_PTH","A patient develops low serum calcium after neck surgery. The nurse reviews the action of parathyroid hormone. What is its usual net effect?","Increase serum calcium","PTH coordinates bone, renal, and vitamin D-related effects that raise circulating calcium.",[["Lower serum calcium","PTH normally raises serum calcium rather than lowering it."],["Increase urinary calcium excretion","PTH promotes renal calcium conservation."],["Retain phosphate by increasing renal phosphate reabsorption","PTH promotes phosphate excretion rather than renal retention."]]);
add("PATH_MSK_PTH__risk","A patient with intact parathyroid glands has a fall in serum calcium. Which physiologic response should the nurse expect?","Increased PTH secretion","Low calcium normally stimulates the parathyroid glands to release PTH.",[["Reduced PTH secretion","Falling serum calcium normally stimulates, rather than suppresses, PTH release."],["Increased calcitonin secretion as the main response","Calcitonin is associated with calcium lowering; hypocalcemia normally stimulates PTH."],["Reduced renal calcium conservation","Losing more calcium would oppose the homeostatic response to hypocalcemia."]]);
add("PATH_MSK_PTH__mechanism","A patient asks why PTH affects both the skeleton and kidneys. Which explanation best connects these effects to calcium homeostasis?","PTH helps mobilize calcium and increases its renal conservation while supporting vitamin D activation","These coordinated actions raise calcium availability rather than acting on bone alone.",[["It lowers calcium by promoting calcium excretion in urine","PTH conserves renal calcium as part of raising serum calcium."],["It acts on the skeleton but has no renal contribution","PTH has important renal effects, including calcium conservation and support of vitamin D activation."],["It raises phosphate by increasing renal phosphate retention","PTH increases phosphate excretion rather than retention."]]);
add("PATH_MSK_PTH__signs","A patient with confirmed hypercalcemia reports constipation, thirst, and generalized weakness. Which interpretation is most appropriate?","These symptoms can accompany elevated serum calcium","Hypercalcemia may affect neuromuscular, gastrointestinal, and renal function.",[["These symptoms establish low serum calcium after parathyroid injury","The case confirms hypercalcemia; hypocalcemia more characteristically produces neuromuscular irritability."],["These symptoms identify a focal peripheral nerve entrapment","Constipation, thirst, and generalized weakness are systemic rather than a localized nerve distribution."],["These symptoms are explained by isolated mechanical back pain","Mechanical back pain does not account for the systemic features accompanying confirmed hypercalcemia."]]);
add("PATH_MSK_PTH__complications","A patient has prolonged excessive PTH activity with increased bone resorption. Which skeletal complication should the nurse anticipate?","Increased risk of pathologic fractures","Excessive chronic resorption can weaken bone and reduce its resistance to fracture.",[["Increased bone mass from net mineral deposition","Prolonged excessive PTH activity with resorption can weaken rather than strengthen bone."],["An acute articular cartilage tear","A cartilage tear is a mechanical joint injury, not the expected result of sustained bone resorption."],["Septic arthritis from direct bacterial invasion","Excess PTH is an endocrine disturbance, not a direct route for bacterial joint infection."]]);
add("PATH_MSK_PTH__tests","A patient is being assessed for a parathyroid-related mineral disorder. Which group of measurements most directly evaluates this system?","Serum calcium, phosphate, and PTH interpreted together","The relationship among calcium, phosphate, and PTH helps characterize a mineral-regulatory disorder.",[["Creatine kinase, urine myoglobin, and potassium","This group evaluates muscle breakdown and its complications rather than the calcium-regulating endocrine system."],["Rheumatoid factor, anti-CCP, and inflammatory markers","This panel addresses inflammatory arthritis rather than a parathyroid mineral disorder."],["Serum calcium measured without a corresponding PTH level","Calcium must be interpreted with PTH to assess whether hormone secretion is appropriate."]]);
add("PATH_MSK_PTH__management","A patient has persistent hypercalcemia from a documented endocrine disorder. Which principle should guide the long-term care plan?","Treat the identified endocrine cause and monitor the calcium disturbance","Lasting management addresses the cause rather than labeling every calcium problem the same way.",[["Treat as nutritional hypocalcemia with routine calcium supplementation","The patient has documented hypercalcemia from an endocrine cause, requiring a cause-directed plan."],["Use analgesics and bone support without endocrine follow-up","Supportive measures do not correct the persistent endocrine source."],["Discontinue follow-up after a single calcium value returns to normal","A transient normal value does not resolve the documented ongoing endocrine disorder."]]);

add("PATH_MSK_osteomalacia","An adult with severe vitamin D deficiency has diffuse bone pain, proximal weakness, and insufficiency fractures. What disorder reflects poor mineralization of newly formed osteoid?","Osteomalacia","Osteomalacia is defective mineralization of mature skeletal osteoid.",[["Osteomyelitis","Bone infection does not explain the documented mineral deficiency and diffuse mineralization problem."],["Inflammatory myopathy","Myopathy may cause proximal weakness but does not define poorly mineralized osteoid and insufficiency fractures."],["Osteoporosis","Osteoporosis is primarily loss of normally mineralized bone quantity, whereas this case specifies failed osteoid mineralization."]]);
add("PATH_MSK_osteomalacia__risk","A patient with severe intestinal malabsorption has very low vitamin D levels and new bone pain. Which mechanism places the patient at risk for osteomalacia?","Inadequate availability of vitamin D and minerals needed for mineralization","Deficient mineral supply or vitamin D activity can impair osteoid mineralization.",[["Excess removal of normally mineralized bone with adequate vitamin D","Net bone loss is distinct from the deficient mineralization associated with severe malabsorption."],["Degeneration of articular cartilage from mechanical loading","Cartilage degeneration does not explain low vitamin D and defective bone mineralization."],["An inflammatory attack confined to joint synovium","Synovitis does not account for the malabsorption-related mineral deficit."]]);
add("PATH_MSK_osteomalacia__mechanism","A bone biopsy contains abundant osteoid that has not mineralized normally. Which process best explains the patient's skeletal weakness?","Failure to adequately mineralize the organic bone matrix","Unmineralized matrix cannot provide normal skeletal rigidity.",[["Primary autoimmune destruction of joint synovium","That is a different inflammatory joint mechanism."],["Sudden displacement of intact joint surfaces","Dislocation does not explain the biopsy finding."],["Loss of bone quantity with normally mineralized remaining matrix","That distinction is more consistent with osteoporosis than osteomalacia."]]);
add("PATH_MSK_osteomalacia__signs","A patient with a mineralization disorder has difficulty rising from a chair and diffuse aching in the pelvis and legs. Which additional feature fits osteomalacia?","Bone tenderness and proximal muscle weakness","Bone pain and proximal weakness are compatible with impaired mineralization.",[["Warm swollen MCP joints with prolonged morning stiffness","That is a synovitis pattern rather than a bone-mineralization symptom pattern."],["A focal tendon defect with loss of its specific movement","An isolated tendon rupture does not account for diffuse bone aching and proximal weakness."],["Bony hand-joint enlargement with short-lived stiffness","That pattern is more characteristic of osteoarthritis."]]);
add("PATH_MSK_osteomalacia__complications","A patient with severe osteomalacia develops pain after minimal stress. Which complication is consistent with poorly mineralized bone?","Insufficiency fractures or pseudofractures","Weak mineralization permits fracture-related defects under ordinary loading.",[["Erosive deformity centered on inflamed small joints","That pattern suggests inflammatory arthritis rather than failure of bone mineralization."],["Recurrent instability from a torn joint ligament","Ligament instability is a different structural problem from stress failure of poorly mineralized bone."],["Focal cortical destruction with an infected draining sinus","That pattern suggests osteomyelitis rather than osteomalacic insufficiency fractures."]]);
add("PATH_MSK_osteomalacia__tests","An adult with diffuse bone pain and suspected osteomalacia is being evaluated. Which laboratory group is most relevant?","Vitamin D, calcium, phosphate, and alkaline phosphatase","These tests help characterize abnormal mineralization and its potential cause.",[["Rheumatoid factor, anti-CCP, and joint-fluid cell count","These evaluate inflammatory joint disease rather than mineralization substrates."],["Creatine kinase, myoglobin, and urine heme","These assess muscle injury rather than the metabolic basis of osteomalacia."],["DXA without biochemical mineral assessment","Low density may be present, but DXA does not identify the underlying mineralization defect."]]);
add("PATH_MSK_osteomalacia__management","A patient has osteomalacia from documented vitamin D deficiency and malabsorption. Which plan targets the cause?","Replace deficient nutrients using an appropriate regimen and address malabsorption","Correcting the underlying deficit supports proper mineralization.",[["Use an antiresorptive regimen without correcting vitamin D depletion","The deficient mineral supply must be addressed rather than treating bone mass alone."],["Increase weight-bearing activity while leaving malabsorption untreated","Exercise does not restore deficient vitamin and mineral availability."],["Provide analgesia and observe the bone pain","Symptom treatment does not correct the documented cause of poor mineralization."]]);

add("PATH_MSK_osteoM","A patient with chronic osteomyelitis has a separated fragment of dead bone within the infected area. What is this fragment called?","Sequestrum","A sequestrum is devitalized bone separated from living bone.",[["Callus","Callus is repair tissue bridging a fracture."],["Tophus","A tophus is a deposit associated with chronic gout."],["Involucrum","Involucrum is the new bone surrounding an infected or necrotic focus."]]);
add("PATH_MSK_osteoM__risk","A patient with an open contaminated tibial fracture asks why bone infection is a concern. Which feature creates a direct infection route?","Communication between the wound and the injured bone","Direct inoculation can introduce organisms into exposed bone.",[["A closed fracture hematoma with an intact skin barrier","A confined hematoma lacks the direct external route created by a communicating wound."],["A superficial abrasion that does not reach the fracture","A superficial noncommunicating lesion is not the same direct route to the broken bone."],["Local swelling without any break in the skin","Swelling itself does not provide environmental organisms direct access to bone."]]);
add("PATH_MSK_osteoM__mechanism","Imaging in chronic osteomyelitis shows new bone surrounding a necrotic focus. Which term describes the surrounding new bone?","Involucrum","Involucrum forms around the infected or devitalized bone focus.",[["Pannus","Pannus is proliferative inflammatory tissue associated with rheumatoid synovitis."],["Tophus","Tophi contain urate deposits."],["Sequestrum","The sequestrum is dead separated bone, not the surrounding new bone."]]);
add("PATH_MSK_osteoM__signs","A patient has persistent focal tibial pain, warmth, and drainage from a sinus after prior surgery. Which interpretation requires follow-up?","Possible chronic osteomyelitis","Persistent local pain and a draining sinus over bone are concerning for chronic bone infection.",[["Uncomplicated remodeling of a healed fracture","Persistent warmth and a draining sinus are not expected findings of uncomplicated remodeling."],["Aseptic postoperative joint stiffness","Stiffness does not explain a chronically draining sinus with focal bone pain."],["Mechanical delayed union without infection","Mechanical problems can cause pain, but warmth and sinus drainage require evaluation for bone infection."]]);
add("PATH_MSK_osteoM__complications","A patient with chronic osteomyelitis has continuing drainage and recurrent pain despite prior treatment. Which complication can perpetuate infection?","Devitalized bone acting as a persistent infectious focus","Necrotic tissue can prevent eradication and may require source control.",[["A well-perfused callus undergoing normal remodeling","Viable healing bone does not describe a persistent infected necrotic focus."],["Joint cartilage wear from altered gait","Degenerative wear may cause pain but does not explain persistent infectious drainage."],["Transient sterile inflammation after a resolved injury","Recurrent pain and continuing drainage argue against a resolved sterile process."]]);
add("PATH_MSK_osteoM__tests","A stable patient with suspected chronic osteomyelitis is being evaluated for organism-directed treatment. Which specimen is most informative when appropriately obtained?","Deep bone or tissue sampling for microbiologic evaluation","A properly obtained deep specimen helps identify the causative organism.",[["Serum inflammatory markers","These may support inflammation but do not identify the causative organism as directly as an appropriate deep specimen."],["Radiographic appearance of the affected bone","Imaging helps define disease but does not provide an organism for targeted antimicrobial selection."],["A swab from the superficial draining sinus","Surface flora may differ from organisms in the infected bone."]]);
add("PATH_MSK_osteoM__management","A patient has chronic osteomyelitis with a sequestrum. Which plan best addresses both the organism and the persistent infected tissue?","Culture-directed antimicrobial therapy with surgical source control when indicated","Treatment may require both targeted antibiotics and removal of devitalized infected tissue.",[["Immobilization and analgesia without organism-directed treatment","These may support comfort but do not treat the infection and necrotic focus."],["A short empiric antibiotic course without reassessment of the sequestrum","Devitalized infected bone can remain a source unless adequately evaluated and treated."],["Surgical removal of the focus without evaluating antimicrobial needs","Source control and appropriate antimicrobial treatment are coordinated in chronic bone infection."]]);

add("PATH_MSK_RA","A patient has bilateral swollen MCP and PIP joints, fatigue, and morning stiffness lasting more than an hour. Which diagnosis best fits this inflammatory pattern?","Rheumatoid arthritis","Symmetric small-joint synovitis with prolonged morning stiffness supports rheumatoid arthritis.",[["Osteoarthritis","Mechanical pain, bony enlargement, and shorter stiffness are more typical than symmetric prolonged inflammatory synovitis."],["Acute gout","Gout usually presents as an acute focal crystal arthritis rather than this persistent symmetric small-joint pattern."],["Septic monoarthritis","A single infected joint does not explain the described bilateral chronic inflammatory distribution."]],"Several small joints in both hands remain swollen, and stiffness limits the first hour of the day. Which inflammatory disorder is most likely?");
add("PATH_MSK_RA__risk","A patient asks whether rheumatoid arthritis is simply an inevitable result of joint wear. Which explanation is most accurate?","It involves immune dysregulation influenced by genetic and environmental factors","RA is an autoimmune inflammatory disorder rather than ordinary wear alone.",[["It primarily reflects mechanical cartilage wear from repeated loading","That mechanism is more characteristic of osteoarthritis."],["It follows deposition of monosodium urate crystals","Urate crystal deposition causes gout rather than rheumatoid autoimmunity."],["It reflects persistent bacterial invasion of the joint space","Bacterial arthritis is a different disease process from rheumatoid immune dysregulation."]]);
add("PATH_MSK_RA__mechanism","A patient with rheumatoid arthritis has progressively eroded joint margins. Which process most directly causes this damage?","Inflammatory synovial pannus damages cartilage and adjacent bone","Proliferative inflammatory tissue drives destructive joint changes in RA.",[["Mechanical thinning of cartilage without inflammatory pannus","That describes a degenerative mechanism rather than rheumatoid erosive synovitis."],["Urate crystals triggering a focal neutrophilic flare","That is the mechanism of gout rather than persistent rheumatoid pannus."],["Loss of bone mineral without inflammation at the joint margins","Generalized mineral loss does not directly explain marginal joint erosions from synovitis."]]);
add("PATH_MSK_RA__signs","A nurse compares patients with chronic hand pain. Which finding most supports rheumatoid arthritis?","Symmetric warm swollen small joints with prolonged morning stiffness","The distribution and sustained stiffness are characteristic of inflammatory synovitis.",[["A single hot first toe beginning overnight","That pattern suggests gout."],["Pain after a fall with a visible joint displacement","That suggests an acute traumatic alignment problem."],["Bony finger enlargement with brief stiffness after rest","That pattern favors degenerative OA."]]);
add("PATH_MSK_RA__complications","A patient with poorly controlled rheumatoid arthritis develops ulnar deviation and increasing difficulty dressing. Which process best explains the functional decline?","Progressive inflammatory joint damage and deformity","Uncontrolled RA can erode joints and alter alignment, impairing function.",[["Muscle deconditioning with preserved joint architecture","Deconditioning may coexist but does not explain ulnar deviation from progressive articular disease."],["A single tendon strain from recent overuse","A focal strain does not explain progressive deformity across affected rheumatoid joints."],["Generalized osteoporosis without inflammatory joint injury","Bone loss can coexist with RA but does not best account for the described articular deformity."]]);
add("PATH_MSK_RA__tests","A patient with symmetric small-joint synovitis is evaluated for rheumatoid arthritis. Which information best supports the assessment?","Clinical joint pattern with inflammatory markers and relevant antibodies such as anti-CCP","RA assessment combines the clinical picture with supportive laboratory findings.",[["Joint-fluid urate crystals and a matching acute monoarthritis","That supports gout rather than the described rheumatoid pattern."],["DXA density and serum calcium","These assess skeletal density and mineral balance rather than rheumatoid synovitis."],["A rheumatoid factor result interpreted without the joint history or examination","An antibody alone is insufficient; the clinical inflammatory pattern remains essential."]]);
add("PATH_MSK_RA__management","A patient with newly diagnosed rheumatoid arthritis uses only occasional analgesics despite persistent swollen joints. Which care goal should the nurse reinforce?","Early disease-modifying treatment to control inflammation and limit joint damage","Disease-modifying therapy addresses the destructive inflammatory process.",[["Use analgesics as the long-term plan while deferring disease modification","Pain relief does not adequately prevent inflammatory joint damage."],["Treat the joints as degenerative disease with exercise and pain control alone","Rehabilitation is helpful, but active RA also requires assessment for disease-modifying treatment."],["Wait for fixed deformities before considering inflammation-directed therapy","Earlier control aims to prevent irreversible damage rather than wait for it."]]);

add("PATH_MSK_OA","A 68-year-old patient has knee pain that worsens with walking, crepitus, and brief morning stiffness. There is no persistent warmth or systemic illness. Which condition is most likely?","Osteoarthritis","Activity-related joint pain with brief stiffness and crepitus supports OA.",[["Rheumatoid arthritis","Persistent inflammatory synovitis and prolonged stiffness are less consistent with this mechanical knee pattern."],["Acute gout","An acute hot swollen crystal-arthritis attack is different from gradual use-related pain and crepitus."],["Septic arthritis","Acute infection typically requires urgent evaluation for a different inflammatory presentation than the described chronic pattern."]]);
add("PATH_MSK_OA__risk","A patient with a prior knee injury and long-term excess mechanical joint loading asks about osteoarthritis risk. Which explanation is most appropriate?","Previous joint injury and mechanical loading can contribute to OA","OA reflects changes across the joint influenced by age, loading, and prior injury.",[["The symptoms are primarily caused by urate crystal deposition","That is gout, not the relationship between prior injury, loading, and OA."],["The prior injury indicates a persistent bacterial joint infection","A past injury does not itself establish infection as the cause of degeneration."],["The mechanical history is less relevant than autoimmune synovitis in OA","Autoimmune synovitis is characteristic of RA; mechanical factors can contribute to OA."]]);
add("PATH_MSK_OA__mechanism","A patient asks what is changing inside an osteoarthritic knee. Which explanation best describes the process?","Degeneration of articular cartilage with changes in the whole joint","OA includes cartilage loss and associated bone and joint-tissue changes.",[["Autoimmune pannus eroding joint margins","That is characteristic of rheumatoid arthritis."],["Urate deposition producing an acute neutrophilic attack","That describes gout rather than the degenerative whole-joint process."],["Failure of newly deposited osteoid to mineralize","That defines osteomalacia, not articular cartilage degeneration."]]);
add("PATH_MSK_OA__signs","A patient has chronic osteoarthritis of the hands. Which finding is most compatible with this diagnosis?","Bony enlargement and activity-related discomfort with brief stiffness","OA commonly produces mechanical symptoms and bony changes.",[["Fever with purulent joint fluid","That raises concern for infection."],["A sudden severely inflamed first toe","That suggests crystal arthritis."],["Persistent symmetric boggy synovitis with prolonged morning stiffness","That is more suggestive of RA."]]);
add("PATH_MSK_OA__complications","A patient with knee osteoarthritis is walking less because of worsening pain and loss of motion. Which complication should the care plan address?","Progressive functional limitation and reduced mobility","Pain, stiffness, and deformity from OA can limit everyday activity.",[["A recurrent acute crystal flare as the cause of declining function","The case attributes the gradual limitations to OA, not documented crystal deposition."],["Progressive nerve ischemia within a tense muscle compartment","This is a different acute emergency, not the typical complication of chronic knee OA."],["Systemic autoimmune inflammation as the explanation for the limited motion","OA can restrict function without rheumatoid systemic autoimmunity."]]);
add("PATH_MSK_OA__tests","A clinician evaluates chronic mechanical knee pain with suspected osteoarthritis. Which finding supports the diagnosis when imaging is indicated?","Joint-space narrowing and compatible degenerative changes on radiographs","Imaging can support the clinical OA pattern when needed.",[["Marginal erosions with a symmetric inflammatory small-joint pattern","That combination is more characteristic of rheumatoid arthritis."],["Needle-shaped negatively birefringent joint-fluid crystals","This supports urate crystal arthritis rather than OA."],["A positive rheumatoid factor without matching inflammatory findings","An isolated antibody result does not establish the cause of this mechanical knee pain."]]);
add("PATH_MSK_OA__management","A patient with knee osteoarthritis wants to maintain independence. Which plan is most appropriate?","Individualized exercise, weight management when indicated, and appropriate pain control","Maintaining strength and function while addressing loading and pain supports OA care.",[["Replace activity with prolonged bed rest to reduce knee loading","Unnecessary inactivity worsens strength and function."],["Use pain medication to maintain the same aggravating impact exercise","Pain control should support an individualized activity plan rather than mask worsening mechanical stress."],["Begin rheumatoid disease-modifying therapy on the basis of OA pain","OA management differs from treatment of autoimmune synovitis."]]);

add("PATH_MSK_AS","A 27-year-old patient has months of low-back and buttock stiffness that improves with exercise but not rest. Sacroiliac imaging shows inflammatory changes. Which disorder best fits?","Ankylosing spondylitis","Inflammatory axial pain with sacroiliac involvement supports axial spondyloarthritis.",[["Acute lumbar muscle strain","A brief mechanical injury does not explain persistent inflammatory sacroiliac changes."],["Osteoporotic compression fracture","A focal fragility fracture has a different presentation."],["Mechanical degenerative back pain","Mechanical symptoms generally worsen with loading rather than improve with exercise in this pattern."]],"A young adult has persistent morning axial stiffness relieved by movement and documented sacroiliitis. Which diagnosis is most likely?");
add("PATH_MSK_AS__risk","A patient with chronic inflammatory back symptoms has a first-degree relative with axial spondyloarthritis. Which interpretation of the family history is most appropriate?","Genetic susceptibility can contribute to risk","Ankylosing spondylitis has a genetic association, although family history alone does not establish the diagnosis.",[["It establishes a mechanical strain as the cause of the current symptoms","A family history of axial spondyloarthritis supports susceptibility to inflammatory axial disease, not an acute strain."],["It establishes the diagnosis without further clinical evaluation","Family history contributes to risk but does not by itself establish disease."],["It means the disease is acquired through household transmission","The association is genetic susceptibility rather than a contagious exposure."]]);
add("PATH_MSK_AS__mechanism","A patient with ankylosing spondylitis develops progressive spinal stiffness. Which process contributes to this change?","Inflammation at axial joints and entheses can lead to new bone formation and fusion","Inflammatory spondyloarthritis can remodel the axial skeleton and restrict motion.",[["A paraspinal muscle tear heals with a localized scar","A focal muscle injury does not account for inflammatory axial fusion."],["Articular cartilage wears down from loading without enthesitis","Mechanical degeneration is different from the inflammatory enthesis and axial process."],["Reduced bone mass compresses several vertebral bodies","Compression fractures can alter posture but do not describe the inflammatory new-bone formation in AS."]]);
add("PATH_MSK_AS__signs","A patient with axial spondyloarthritis reports difficulty taking a deep breath. Which examination finding is consistent with axial involvement?","Reduced chest expansion with spinal and costovertebral stiffness","Involvement of the axial skeleton can limit chest-wall mobility.",[["A normal spinal examination with isolated calf muscle tenderness","That does not account for restricted chest-wall movement from axial involvement."],["Pain confined to one acutely sprained ankle ligament","A peripheral traumatic sprain does not explain spinal and costovertebral restriction."],["Normal chest expansion with brief back pain after lifting","That is more compatible with a mechanical episode than restricted inflammatory axial motion."]]);
add("PATH_MSK_AS__complications","A patient with advanced ankylosing spondylitis has increasing forward spinal curvature and limited neck rotation. Which complication is developing?","Progressive axial rigidity and kyphotic deformity","Chronic axial inflammation and structural change can markedly restrict movement.",[["An isolated lumbar muscle strain","A strain does not account for progressive fixed axial rigidity and curvature."],["A partially displaced shoulder joint","A shoulder subluxation does not explain the evolving axial deformity."],["General deconditioning with preserved spinal mobility","Deconditioning alone does not explain progressive structural restriction of spinal motion."]]);
add("PATH_MSK_AS__tests","A young adult has persistent inflammatory back pain. Which evaluation most directly helps assess suspected ankylosing spondylitis?","Sacroiliac imaging interpreted with the inflammatory history and examination","The distribution of inflammation and clinical pattern support diagnosis.",[["Lumbar bone-density measurement","DXA assesses bone mass rather than sacroiliac inflammatory changes."],["Joint-fluid analysis from an acutely inflamed peripheral joint","Aspiration may evaluate another joint problem but does not directly assess the axial inflammatory pattern."],["HLA-B27 testing interpreted without the clinical history","The marker supports susceptibility but is not independently diagnostic."]]);
add("PATH_MSK_AS__management","A patient with ankylosing spondylitis asks how to preserve function. Which plan is most appropriate?","Maintain prescribed mobility and posture exercises with appropriate anti-inflammatory treatment","Exercise and disease-directed treatment help preserve movement and control symptoms.",[["Use prolonged bed rest as the main strategy for spinal stiffness","Inactivity does not preserve the mobility and posture threatened by axial disease."],["Treat symptoms with analgesia while discontinuing mobility exercises","Symptom relief does not replace the function-preserving exercise component."],["Use intermittent bracing in place of prescribed anti-inflammatory care","Support alone does not control the inflammatory process or replace the individualized treatment plan."]]);

add("PATH_MSK_gout","A patient awakens with sudden severe pain, warmth, and swelling at the first metatarsophalangeal joint. Aspirated fluid contains needle-shaped negatively birefringent crystals. Which diagnosis is supported?","Gout","Monosodium urate crystals with an acute inflammatory attack support gout.",[["Osteoarthritis","OA does not produce this characteristic urate-crystal pattern."],["A ligament sprain","A sprain does not explain the aspirated crystals."],["Calcium pyrophosphate crystal arthritis","CPP crystals have a different characteristic shape and birefringence."]],"An acutely inflamed first toe yields needle-shaped negatively birefringent crystals on aspiration. Which crystal arthropathy is most likely?");
add("PATH_MSK_gout__risk","A patient with recurrent gout has persistently elevated serum urate and reduced renal urate clearance. Which factor explains the tendency to form urate deposits?","Urate accumulation from inadequate excretion relative to production","Hyperuricemia increases the potential for monosodium urate crystal deposition.",[["Reduced calcium deposition into newly formed osteoid","Deficient mineralization causes a different skeletal disorder, not urate accumulation."],["Mechanical wear of articular cartilage","Degenerative cartilage loss does not explain persistently elevated serum urate from reduced clearance."],["Increased renal urate removal relative to production","Greater urate removal would oppose accumulation rather than promote the described deposits."]]);
add("PATH_MSK_gout__mechanism","A patient asks why urate crystals cause an intensely painful swollen joint. Which explanation is most accurate?","Crystals trigger an acute inflammatory response involving neutrophils","The inflammatory reaction to deposited monosodium urate produces the attack.",[["Autoimmune pannus gradually erodes the synovial margins","Pannus is characteristic of RA, not the acute urate-triggered response."],["Mechanical cartilage abrasion causes the entire attack","The question describes crystal-triggered inflammation rather than ordinary mechanical wear."],["Bacteria multiply within the synovial fluid","Infection is an important competing diagnosis but is not the mechanism by which urate crystals cause gout."]]);
add("PATH_MSK_gout__signs","A patient with previous gout reports a new episode of abrupt monoarticular pain and swelling. Which finding is characteristic of an acute flare?","A very tender, warm, red, swollen joint","Acute gout commonly causes intense inflammatory monoarthritis.",[["Bony enlargement with pain on use and brief morning stiffness","That pattern is more compatible with osteoarthritis than an abrupt inflammatory flare."],["Diffuse soft-tissue pain without objective joint inflammation","That does not describe a localized acutely inflamed gouty joint."],["Symmetric small-joint swelling with hours of morning stiffness over months","That chronic distribution is more suggestive of rheumatoid arthritis."]]);
add("PATH_MSK_gout__complications","A patient with longstanding poorly controlled gout has firm nodules near joints and recurrent attacks. Which complication best explains the nodules?","Tophi from accumulated urate deposits","Chronic urate deposition can form tophi and contribute to joint damage.",[["Osteophytes from degenerative joint remodeling","Osteophytes are bony outgrowths, not nodules of accumulated urate."],["Rheumatoid nodules associated with autoimmune disease","The history is poorly controlled gout, which produces tophi from urate deposition."],["Sequestra from necrotic infected bone","A sequestrum is dead bone in osteomyelitis rather than a gouty soft-tissue deposit."]]);
add("PATH_MSK_gout__tests","A patient has a new acutely swollen joint and possible gout. Which finding most directly supports urate crystal arthritis?","Monosodium urate crystals identified in joint fluid","Crystal identification supports the diagnosis; infection must also be considered when clinically indicated.",[["Joint-space narrowing on a plain radiograph","This is not specific for urate crystals in a newly swollen joint."],["A raised C-reactive protein","Inflammatory markers can rise in several arthritides and do not identify the crystal type."],["An elevated serum urate concentration","Hyperuricemia supports risk but does not confirm that the current arthritis is caused by urate crystals."]]);
add("PATH_MSK_gout__management","A patient asks whether medication for an acute gout flare and long-term urate control have the same purpose. Which explanation is best?","Flare treatment controls inflammation; indicated urate-lowering therapy addresses recurrent crystal burden","The immediate inflammatory attack and long-term urate accumulation are related but distinct treatment targets.",[["Both regimens primarily rebuild damaged articular cartilage","Flare treatment controls inflammation and urate-lowering treatment reduces crystal burden; neither is principally cartilage replacement."],["Long-term urate lowering replaces evaluation and treatment of an acute hot joint","Long-term prevention does not substitute for assessment and appropriate acute treatment."],["Successful pain relief from one flare removes the underlying urate burden","Anti-inflammatory symptom relief does not itself eliminate accumulated urate."]]);

add("PATH_MSK_fibro","A patient has widespread pain for six months, unrefreshing sleep, fatigue, and difficulty concentrating. Examination shows diffuse soft-tissue tenderness without synovitis. An appropriate evaluation has not identified another cause. Which diagnosis fits best?","Fibromyalgia","The combination of widespread pain, sleep disturbance, cognitive symptoms, and absent destructive synovitis supports fibromyalgia.",[["Rheumatoid arthritis","The case lacks the objective inflammatory synovitis expected to explain RA-related joint pain."],["A regional muscle strain","A focal injury does not explain six months of widespread pain with sleep, fatigue, and cognitive symptoms."],["Osteomalacia","Mineralization disease can produce pain and weakness, but the appropriate negative evaluation and multisymptom soft-tissue pattern support fibromyalgia."]],"A patient has persistent widespread pain, nonrestorative sleep, and cognitive symptoms without objective synovitis after evaluation for alternative causes. Which diagnosis is most likely?");
add("PATH_MSK_fibro__risk","A patient asks whether fibromyalgia requires a prior physical injury. Which explanation is most appropriate?","It is multifactorial, and a single injury is not required","Genetic and environmental factors may contribute; no single precipitating injury is necessary.",[["A physical injury must precede the onset","Fibromyalgia can occur without a required preceding physical injury."],["It is acquired through a bacterial infection in painful joints","Fibromyalgia is not defined by bacterial joint infection."],["One stressful event establishes the diagnosis","Stress may be relevant but does not replace assessment of the clinical symptom pattern and competing causes."]]);
add("PATH_MSK_fibro__mechanism","A patient with fibromyalgia asks why pain is widespread despite no erosive arthritis. Which explanation best describes the proposed pain mechanism?","Altered processing and amplification of pain signals","Fibromyalgia is associated with changes in pain processing rather than typical destructive joint inflammation.",[["Autoimmune erosion of joint surfaces","Fibromyalgia does not require erosive synovitis as its pain mechanism."],["A persistent focal muscle tear at each tender area","The widespread pain is not explained by multiple required local tears."],["Deficient mineralization of newly formed bone","That is osteomalacia rather than altered pain processing."]]);
add("PATH_MSK_fibro__signs","A patient is assessed for fibromyalgia. Which symptom cluster is most compatible with the condition?","Widespread pain with fatigue, poor sleep, and cognitive complaints","Fibromyalgia commonly involves multiple pain-related and nonpain symptoms.",[["Localized pain reproduced by one recently injured tendon","That is a regional injury pattern rather than the widespread multisymptom pattern."],["Activity-related joint pain with bony enlargement and brief stiffness","That more strongly supports degenerative joint disease."],["Persistent warm swollen small joints with erosions","Objective erosive synovitis suggests inflammatory arthritis rather than fibromyalgia alone."]]);
add("PATH_MSK_fibro__complications","A patient with fibromyalgia has stopped social activities because of pain, fatigue, and poor sleep. Which complication should the nurse address?","Reduced daily function and quality of life","Fibromyalgia can substantially impair function even without erosive joint damage.",[["Progressive joint erosion as the source of the disability","Fibromyalgia can impair function without causing destructive inflammatory joint changes."],["A chronic infected bone focus causing the fatigue","Bone infection is a different cause requiring separate evidence."],["Skeletal fragility caused by widespread loss of mineralization","Fibromyalgia does not itself establish a mineralization defect."]]);
add("PATH_MSK_fibro__tests","A patient asks which blood test will definitively confirm fibromyalgia. Which response is most accurate?","Diagnosis is clinical; directed evaluation helps identify competing causes","There is no single routine confirmatory blood test for fibromyalgia.",[["A positive rheumatoid factor is the confirming test","Rheumatoid factor is not a diagnostic biomarker for fibromyalgia."],["A muscle enzyme elevation is required before diagnosis","A specific CK elevation is not required to establish the clinical fibromyalgia pattern."],["Normal imaging alone establishes the diagnosis","Normal imaging does not by itself establish the required clinical symptom pattern or exclude competing causes."]]);
add("PATH_MSK_fibro__management","A patient with fibromyalgia wants to increase function but fears activity will cause joint destruction. Which plan is most appropriate?","Use individualized graded activity, sleep strategies, education, and appropriate symptom treatment","A multimodal plan supports function without treating fibromyalgia as a destructive joint disease.",[["Avoid activity until pain has completely disappeared","Waiting for total pain resolution can prolong inactivity rather than support graded functional recovery."],["Use rheumatoid disease-modifying therapy without inflammatory arthritis","Fibromyalgia management differs from immunosuppressive treatment for erosive synovitis."],["Use passive symptom treatment without a gradual self-management plan","An individualized active plan addresses sleep, activity tolerance, and daily function."]]);

add("MSK_fracture","After a fall, an adult has severe focal forearm pain, swelling, deformity, and an X-ray showing a break in the radius. Which injury is present?","Fracture","The radiograph demonstrates a disruption in the continuity of bone.",[["A muscle strain alone","A muscle strain does not account for the demonstrated bony break."],["A ligament sprain alone","A ligament lesion does not explain the radiographic break."],["Subluxation without a fracture","Partial joint displacement is not the fracture shown here."]]);
add("MSK_fracture__risk","A patient with known osteoporosis sustains a wrist fracture after a fall from standing height. Which factor best explains why this minor event caused a fracture?","Reduced bone strength allowed low-energy trauma to exceed its load tolerance","Fragile bone can fail under forces tolerated by stronger bone.",[["A fall must produce a joint dislocation before it can break bone","Bone can fracture without preceding dislocation."],["The injury is necessarily a ligament sprain because the fall was low energy","Osteoporotic bone can fracture after low-energy trauma."],["The pain is caused by muscle damage despite the documented wrist fracture","The established fragility fracture is explained by reduced skeletal load tolerance."]]);
add("MSK_fracture__mechanism","A patient asks what distinguishes a fracture from a sprain after an accident. Which explanation is accurate?","A fracture disrupts bone continuity; a sprain injures ligament tissue","The injured tissue differentiates these two types of trauma.",[["A fracture injures muscle; a sprain disrupts bone","The defining tissues are bone for fracture and ligament for sprain."],["A fracture separates joint surfaces; a sprain breaks the cortex","Joint separation describes dislocation, while cortical interruption is a fracture."],["A fracture and a sprain are distinguished by pain severity","Injury type depends on the damaged structure rather than pain alone."]]);
add("MSK_fracture__signs","After a leg injury, a patient has deformity and severe focal pain. Which finding should prompt immediate additional neurovascular assessment?","New numbness or loss of movement distal to the injury","Distal neurologic changes can indicate injury-related compromise requiring urgent attention.",[["Focal tenderness when the injured bone is palpated","Tenderness supports local injury but is less specific for a new distal neurovascular complication."],["Bruising limited to the impact area","Bruising does not indicate the same threatened distal function as new numbness or weakness."],["Swelling without a change in distal sensation or movement","Swelling needs monitoring, but new sensory or motor loss specifically calls for additional neurovascular assessment."]]);
add("MSK_fracture__complications","A patient with a long-bone fracture develops new distal numbness and a cool foot. Which complication must be evaluated promptly?","Neurovascular compromise associated with the injury","Fractures can injure or compress nearby nerves and vessels.",[["Expected local bruising during early healing","A cool foot and new numbness are not explained by uncomplicated bruising."],["Delayed union from inadequate callus","Delayed union is a later healing issue and does not explain acute distal perfusion changes."],["Isolated pain from muscle spasm around the fracture","Muscle spasm does not adequately explain a new cool numb foot."]]);
add("MSK_fracture__tests","A patient with a suspected forearm fracture is awaiting imaging. Which assessment should the nurse perform in addition to preparing for radiographs?","Evaluate distal circulation, sensation, and motor function","Imaging defines the bony injury, while examination identifies threatened nerves or vessels.",[["Record swelling and the visible degree of deformity","These are important but do not replace the distal circulation, sensation, and motor baseline."],["Assess pain relief after prescribed medication","Analgesic response does not establish distal nerve and vessel function."],["Measure active motion of the injured arm without a distal assessment","Movement of an injured limb is not a substitute for a careful neurovascular examination."]]);
add("MSK_fracture__management","A patient has a displaced fracture requiring stabilization. Which plan addresses the essential structural goals of treatment?","Restore acceptable alignment and maintain appropriate immobilization or fixation","Fracture treatment aims to support union while protecting function and surrounding tissues.",[["Use analgesia while allowing displaced fragments to remain mobile","Comfort measures do not restore alignment or provide the stability needed for healing."],["Begin strengthening before determining fracture stability","Premature loading can disrupt alignment and does not address the initial structural goal."],["Apply a support chosen for comfort without confirming acceptable alignment","Stabilization must maintain acceptable fracture position rather than provide comfort alone."]]);

add("MSK_healing","A patient still has pain and movement at a fracture site months after injury. Serial images show little progression toward union. Which problem is most concerning?","Impaired fracture healing with possible nonunion","Persistent instability and absent expected progression raise concern for failed union.",[["Expected early inflammatory swelling only","The prolonged course is beyond initial inflammation."],["A resolved fracture with normal stability","Persistent motion and absent progression argue against this."],["Normal remodeling after secure union","Remodeling occurs after an adequate bony connection has formed."]]);
add("MSK_healing__risk","A patient with a fracture has poor arterial supply and ongoing infection near the injury. Why is healing at increased risk?","Both impaired perfusion and infection can interfere with union","Healing depends on viable tissue, circulation, and control of infection.",[["Infection supplies the inflammatory stimulus needed for faster union","Infection can disrupt healing rather than serve as a desirable healing stimulus."],["Reduced perfusion protects the callus from inflammatory injury","Poor circulation limits the oxygen and nutrients needed for repair."],["Maintained alignment offsets the effects of infection and poor circulation","Mechanical alignment is important but cannot remove these biological barriers."]]);
add("MSK_healing__mechanism","A patient's fracture site remains mechanically unstable during attempted healing. Which explanation connects this instability to failed union?","Excessive motion can prevent a stable bony bridge from developing","Repair requires sufficient mechanical stability for effective union.",[["Persistent motion indicates that normal remodeling is already complete","A mobile site is not secure bony union."],["Instability improves healing by repeatedly recreating the initial hematoma","Repeated disruption does not substitute for a stable healing environment."],["Pain relief from medication confirms the fragments are mechanically united","Pain control does not establish fracture stability or bridging bone."]]);
add("MSK_healing__signs","Several months after a fracture, which finding should the nurse report as a possible sign of delayed union rather than ordinary improvement?","Persistent focal pain and abnormal movement at the fracture site","Ongoing pain and instability may indicate inadequate union.",[["Steadily improving supported function","Improvement is generally more compatible with recovery."],["Decreasing swelling with increasing stability","These are reassuring trends."],["Mild residual stiffness despite documented progressive union","Stiffness alone is less specific for delayed bony healing."]]);
add("MSK_healing__complications","A fracture heals with the fragments in poor alignment, leaving a visible angular deformity. What is this complication called?","Malunion","Malunion means union has occurred in an unacceptable position.",[["Delayed union","Delayed union means slow progress, not completed healing in an abnormal alignment."],["Loss of reduction before healing","Loss of reduction is a change in fragment position; the question describes the final healed deformity."],["Nonunion","Nonunion is failure to achieve bony union rather than a fracture that has united in poor alignment."]]);
add("MSK_healing__tests","A clinician suspects delayed union after a long-bone fracture. Which comparison is most useful?","Serial images and examination for progressive bridging and stability","Interval assessment helps distinguish slow progress from persistent failure to unite.",[["Compare pain scores before and after analgesia","Medication response does not demonstrate progressive union."],["Compare DXA measurements at the lumbar spine","Generalized density does not establish local fracture bridging."],["Compare serum calcium concentrations over several visits","Calcium values do not directly document local structural union or mechanical stability."]]);
add("MSK_healing__management","A patient has nonunion associated with instability and a suspected infected focus. Which plan best addresses the contributors?","Evaluate and treat infection and restore suitable stability, with revision or grafting when indicated","Management targets biological and mechanical barriers to union.",[["Increase loading to stimulate healing before assessing the unstable site","The mechanical and infectious causes need evaluation before a safe loading plan can be chosen."],["Extend pain treatment without reassessing the fracture mechanics","Analgesia does not correct instability or an infected focus."],["Revise stabilization while leaving suspected infection unevaluated","Both mechanical and biological contributors need attention."]]);

add("MSK_fat_embolus","Thirty-six hours after a femoral fracture, a patient develops hypoxemia, confusion, and a fine petechial rash over the upper chest. Which syndrome is most concerning?","Fat embolism syndrome","Respiratory, neurologic, and petechial findings after a long-bone fracture support fat embolism syndrome.",[["Aspiration pneumonitis","Aspiration can cause hypoxemia but does not best explain the delayed post-long-bone-fracture combination with confusion and petechiae."],["Isolated opioid-related respiratory depression","Sedation may impair breathing but does not account for this characteristic multisystem pattern and rash."],["Thrombotic pulmonary embolism","Thrombotic PE is important to consider, but the delayed long-bone injury with petechiae and neurologic changes points to fat embolism syndrome."]],"A patient becomes hypoxemic and confused the day after a major long-bone injury, with new upper-body petechiae. Which complication best explains the combination?");
add("MSK_fat_embolus__risk","A nurse monitors several orthopedic patients. Which patient has the greatest specific risk for fat embolism syndrome?","A patient with a recent femoral shaft fracture","Major long-bone and pelvic injuries can release marrow fat into the circulation.",[["A patient with an isolated ankle ligament sprain","A ligament injury does not expose long-bone marrow in the way a femoral shaft fracture can."],["A patient with a superficial hip contusion and no fracture","A superficial bruise lacks the major marrow-containing bone injury described in the highest-risk choice."],["A patient with a stable distal finger fracture","This smaller isolated injury carries less specific risk than a major femoral shaft fracture."]]);
add("MSK_fat_embolus__mechanism","Following a long-bone fracture, a patient develops fat embolism syndrome. Which explanation best describes the pathophysiology?","Marrow fat enters the circulation and contributes to microvascular obstruction and inflammatory injury","Both embolic and inflammatory effects help explain pulmonary and systemic findings.",[["A venous thrombus migrates into a pulmonary artery","That describes thrombotic embolism rather than marrow-fat-associated microvascular injury."],["A pleural tear allows air to collapse the lung","Pneumothorax is a different traumatic respiratory mechanism."],["Aspiration introduces gastric material into the airways","Aspiration injury is not the marrow-fat mechanism following long-bone trauma."]]);
add("MSK_fat_embolus__signs","A patient is being observed after multiple long-bone fractures. Which new finding cluster requires urgent evaluation for fat embolism syndrome?","Respiratory distress, altered mentation, and petechiae","The combined systemic pattern is characteristic in the appropriate post-traumatic setting.",[["Hypoventilation and sleepiness immediately after an opioid dose without a rash","This pattern suggests medication effect rather than the characteristic fat embolism multisystem cluster."],["Unilateral calf discomfort without hypoxemia or neurologic change","Local leg symptoms alone do not describe fat embolism syndrome."],["Localized fracture pain and swelling with stable breathing and mentation","These can be local injury findings without the respiratory and neurologic syndrome."]]);
add("MSK_fat_embolus__complications","A patient with suspected fat embolism syndrome has worsening oxygen saturation and increasing work of breathing. Which complication is the immediate concern?","Severe hypoxemic respiratory failure","Pulmonary microvascular and inflammatory injury can compromise gas exchange.",[["Isolated atelectasis with normal oxygenation","The worsening oxygen saturation and work of breathing indicate a more serious oxygenation threat."],["Local wound infection as the immediate cause of distress","The immediate problem in this presentation is progressive respiratory compromise."],["Delayed bony union without systemic instability","Bony union is a later issue and does not address the current hypoxemia."]]);
add("MSK_fat_embolus__tests","A patient with a recent femoral fracture develops sudden confusion and tachypnea. Which assessment has immediate priority while the cause is investigated?","Assess oxygenation, respiratory effort, and overall clinical stability","Recognizing and responding to impaired oxygenation is essential in this time-sensitive presentation.",[["Repeat the local fracture-alignment examination","Fracture reassessment matters, but airway, breathing, and systemic stability take priority."],["Obtain a detailed history of baseline cognitive function","Baseline information is useful but should not delay immediate oxygenation assessment in new tachypnea and confusion."],["Inspect the skin for a petechial rash before checking breathing","The rash may aid recognition, but respiratory assessment must not be delayed."]]);
add("MSK_fat_embolus__management","A patient with fat embolism syndrome becomes hypoxemic after a femoral fracture. Which care priority is most appropriate?","Support oxygenation and hemodynamics while coordinating definitive trauma care","Treatment is supportive and addresses respiratory and circulatory compromise alongside fracture management.",[["Prioritize rash treatment while awaiting improvement in oxygenation","The potentially life-threatening respiratory and hemodynamic problems take priority."],["Start routine rehabilitation before stabilizing breathing","Mobilization planning follows stabilization of the acute systemic complication."],["Use a thrombotic-embolism regimen without assessing the suspected syndrome","Fat embolism syndrome requires supportive stabilization and diagnostic assessment rather than assuming a confirmed thrombotic PE."]]);

add("MSK_strain","A recreational athlete feels a sudden pull in the posterior thigh while sprinting. Examination identifies a tear in the hamstring muscle-tendon unit. What type of injury is present?","Strain","A strain affects muscle or tendon rather than a ligament.",[["Dislocation","No loss of joint alignment is described."],["Fracture","The documented tear involves soft tissue rather than bone."],["Sprain","A sprain affects a ligament, not the muscle-tendon unit."]]);
add("MSK_strain__risk","A patient begins repeated heavy lifting without gradual conditioning and develops a muscle-tendon injury. Which mechanism best explains the strain?","Excess load or overstretching of the muscle-tendon unit","Strains may follow abrupt force or repetitive overuse.",[["Force tears the ligament connecting two bones","That mechanism defines a sprain rather than a muscle-tendon strain."],["A compressive load interrupts bone continuity","Bone disruption is a fracture, not the described muscle-tendon injury."],["The joint surfaces partly lose normal contact","Partial displacement defines subluxation rather than strain."]]);
add("MSK_strain__mechanism","A patient asks what was damaged in a hamstring strain. Which explanation is most accurate?","Muscle or tendon fibers were stretched beyond tolerance and disrupted","A strain involves the contractile or tendon portion of the muscle-tendon unit.",[["The articular surfaces completely lost contact","That defines a dislocation."],["The bone separated into several fragments","That describes a comminuted fracture."],["Only the ligament connecting two bones was torn","That is a ligament sprain rather than a hamstring strain."]]);
add("MSK_strain__signs","A patient reports pain after an acute calf muscle injury. Which finding is compatible with a strain?","Localized tenderness and weakness with pain during use of the injured muscle","Strains commonly impair contraction and function of the involved muscle-tendon unit.",[["A fixed joint deformity after complete displacement","A dislocation is a different injury from a calf muscle strain."],["Focal bone tenderness with a visible cortical break","A cortical break supports fracture rather than strain."],["Joint-line instability when a supporting ligament is stressed","Instability on ligament testing suggests a sprain rather than injury localized to the muscle-tendon unit."]]);
add("MSK_strain__complications","An athlete returns to full-speed sprinting before a hamstring strain has recovered. Which problem should the nurse emphasize?","Reinjury and persistent loss of strength","Premature loading can disrupt recovery and increase recurrence.",[["A fixed fracture deformity from malunion","Malunion follows a broken bone, not the described incompletely recovered muscle strain."],["Persistent joint displacement from an unreduced dislocation","The injury described is to the hamstring muscle-tendon unit rather than joint congruity."],["Resolution of risk once visible bruising fades","Bruising can improve before muscle strength and load tolerance recover."]]);
add("MSK_strain__tests","A patient has marked weakness after a suspected severe tendon injury. Which evaluation is most appropriate?","Focused functional examination with imaging when the severity or structure requires clarification","Assessment localizes the injury and guides whether further imaging is needed.",[["A radiograph as the measure of tendon continuity","Radiographs may identify an associated bony injury but do not directly characterize most tendon tears."],["Inflammatory markers to determine whether the tendon is intact","Inflammatory markers do not establish mechanical continuity or functional severity."],["A pain score without evaluating strength or movement","Marked weakness requires a functional and structural assessment beyond symptom scoring."]]);
add("MSK_strain__management","A patient with an evaluated uncomplicated muscle strain asks when to resume full activity. Which instruction is best?","Use relative rest followed by graded rehabilitation and strengthening as recovery permits","Activity should progress with tissue recovery and restoration of function.",[["Return to maximal sprinting once resting pain decreases","Resting comfort does not prove the injured unit can tolerate maximal loading."],["Continue complete immobilization after function begins to return","Unnecessary prolonged immobilization can impair recovery; progression should be individualized."],["Base return to sport on disappearance of skin bruising","Visible bruising is not an adequate measure of strength and tissue recovery."]]);

add("MSK_dislocation","After a fall, a patient's shoulder is deformed and painful. Imaging shows complete loss of contact between the humeral head and glenoid. Which injury is present?","Dislocation","Complete loss of normal articular contact defines a dislocation.",[["Comminuted fracture","Multiple bone fragments are not the alignment finding described."],["Isolated muscle strain","A strain does not describe complete joint displacement."],["Subluxation","Subluxation retains some normal joint contact."]]);
add("MSK_dislocation__risk","A patient with prior shoulder instability sustains a new traumatic displacement during sport. Which factor contributes to recurrence?","Damage or laxity in the structures stabilizing the joint","Compromised capsular and ligamentous support can permit recurrent dislocation.",[["Reduced bone density as the primary cause of ligamentous restraint failure","Low density can predispose to fracture but does not directly explain recurrent soft-tissue instability."],["Cartilage wear without loss of stabilizing support","Cartilage degeneration alone does not explain recurrent traumatic displacement."],["Restored capsular tension and balanced supporting muscles","These factors improve stability rather than contribute to recurrence."]]);
add("MSK_dislocation__mechanism","A patient asks what distinguishes a dislocation from a subluxation. Which explanation is correct?","A dislocation completely disrupts normal contact between joint surfaces","The extent of lost congruity differentiates full dislocation from partial displacement.",[["A dislocation means a break through the adjacent bone","Bone interruption defines fracture rather than loss of joint congruity."],["A dislocation means tearing of a muscle-tendon unit","That defines strain rather than joint displacement."],["A dislocation retains partial contact between the joint surfaces","Partial retained contact describes subluxation rather than complete dislocation."]]);
add("MSK_dislocation__signs","After a shoulder injury, a patient has visible deformity and cannot move the arm normally. Which additional finding requires prompt neurovascular assessment?","New numbness or weakness distal to the joint","Displacement can affect nearby nerves or vessels.",[["Localized tenderness over the injured shoulder","Tenderness is expected but does not identify the same additional neurovascular threat as distal weakness or numbness."],["Bruising around the joint with unchanged distal function","Bruising needs documentation but is less specific for nerve or vessel compromise."],["Pain that improves with support while distal sensation remains intact","Improved pain with intact distal function is less concerning than a new sensory or motor deficit."]]);
add("MSK_dislocation__complications","A patient with a hip dislocation has a new distal sensory deficit. Which complication should the nurse communicate immediately?","Associated nerve injury or compression","Displaced joint anatomy can injure nearby nerves and vessels.",[["Routine muscle soreness without nerve involvement","A new distal sensory deficit after hip dislocation suggests more than expected soreness."],["Delayed fracture union","No fracture-healing problem explains the new sensory change in this presentation."],["Pain-related guarding with intact nerve function","Guarding can limit movement, but a new sensory deficit requires evaluation for nerve injury."]]);
add("MSK_dislocation__tests","A patient is evaluated for a traumatic shoulder dislocation. Which assessment should be compared before and after reduction?","Distal perfusion, sensation, and motor function","Serial neurovascular assessment detects injury-associated or procedure-associated changes.",[["Pain score and the dose of analgesia required","Pain response is important but does not document nerve and vessel status before and after reduction."],["Visible joint contour and radiographic alignment","These establish position but do not replace the distal neurovascular comparison."],["Passive range of motion at the shoulder","Motion testing does not adequately assess distal perfusion, sensation, and motor function."]]);
add("MSK_dislocation__management","A patient with a traumatic shoulder dislocation asks a friend to pull the arm back into place. Which response is most appropriate?","Arrange prompt qualified reduction with appropriate assessment and subsequent stabilization","Trained reduction and neurovascular evaluation reduce the risk of additional harm.",[["Use a sling and defer evaluation until the pain settles","A displaced joint needs prompt qualified assessment rather than delayed symptom observation."],["Begin assisted range-of-motion exercises before confirming alignment","Exercise is not a substitute for assessment and qualified reduction of a dislocated joint."],["Allow reduction by the friend if analgesia has reduced the pain","Pain relief does not make an untrained manipulation safe or replace neurovascular assessment."]]);

add("PATH_MSK_RA__RA_OA_compare","Two patients report hand pain. One has symmetric swollen MCP joints with stiffness lasting over an hour; the other has activity-related pain and bony enlargement with brief stiffness. Which finding favors rheumatoid arthritis?","Symmetric inflammatory synovitis with prolonged morning stiffness","The inflammatory joint pattern distinguishes RA from the more mechanical OA presentation.",[["Activity-related pain with crepitus and short-lived stiffness","That pattern favors mechanical degeneration rather than persistent rheumatoid synovitis."],["A single abruptly red first toe with urate crystals","That finding supports gout rather than the rheumatoid small-joint pattern."],["Bony finger enlargement without warm swollen MCP joints","Bony enlargement with less inflammatory swelling is more compatible with OA."]],"A patient has bilateral boggy MCP swelling and prolonged stiffness, while another has bony finger enlargement and load-related pain. Which pattern is more consistent with RA?");
add("MSK_fracture__fracture_patterns","A radiograph after a high-energy injury shows the femoral shaft broken into four separate fragments. How should the fracture pattern be classified?","Comminuted fracture","A comminuted fracture contains multiple fragments, typically three or more.",[["Greenstick fracture","A greenstick fracture is an incomplete bending fracture."],["Transverse two-fragment fracture","That description does not account for the several fragments shown."],["Oblique two-fragment fracture","An angled break with two main fragments does not describe this multifragmentary injury."]]);

// More closely related clinical alternatives for upper tiers. They are tied
// to each vignette's criterion rather than borrowed from another answer pool.
function advanced(id:string,d:[string,string][],stem?:string){mskCases[id].harderFoils=d.map(([text,why])=>({text,why}));if(stem)mskCases[id].harderStem=stem;}
advanced("PATH_MSK_stages",[["Inflammatory stage","Inflammation precedes formation of the described bridging fibrocartilage."],["Remodeling stage","Remodeling reorganizes a previously formed bony bridge."],["Initial hematoma stage","The initial clot does not explain a soft bridging callus."]]);
advanced("PATH_MSK_stages__risk",[["Osteoclast-mediated remodeling of an established callus","That is a later repair activity, not the initiating traumatic event."],["Osteoblast mineralization of the final bony bridge","This follows the initial vascular injury."],["Inflammatory erosion of articular cartilage","That is not the initiating event in a traumatic fracture hematoma."]],"Immediately after a displaced femoral fracture, a local hematoma forms. Which event started the repair cascade?");
advanced("PATH_MSK_stages__mechanism",[["Resorption of the bridge faster than new bone can replace it","Unbalanced resorption would weaken the bridge rather than restore normal architecture."],["Continued fibrocartilaginous bridging as the mature endpoint","The reparative bridge must progress toward organized mineralized bone, not remain immature cartilage."],["Development of a mobile fibrous articulation between fragments","A pseudarthrosis reflects failed union rather than normal progression after a reparative bridge."]]);
